package com.hbm.client.rotaryfurnace;
import com.hbm.client.gui.LegacyContainerScreen;
import com.hbm.fluid.FluidTank;
import com.hbm.item.fluid.client.FluidInfo;
import com.hbm.machine.rotaryfurnace.*;
import com.hbm.material.HbmMaterials;
import com.mojang.blaze3d.systems.RenderSystem;
import com.mojang.blaze3d.vertex.*;
import java.util.*;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.renderer.GameRenderer;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
/** Original176x186/256atlas GUI, three native fluid gauges and tinted/additive molten gauge. */
public final class RotaryFurnaceScreen extends LegacyContainerScreen<RotaryFurnaceMenu> {
 public RotaryFurnaceScreen(RotaryFurnaceMenu menu,Inventory player,Component title){super(menu,player,title,ResourceLocation.parse("hbm:textures/gui/processing/gui_rotary_furnace.png"),176,186);}
 private RotaryFurnaceEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position) instanceof RotaryFurnaceEntity furnace?furnace:null;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,61-font.width(title)/2,6,4210752,false);g.drawString(font,playerInventoryTitle,8,92,4210752,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);var furnace=machine();if(furnace==null)return;drawLegacyRegion(g,63,30,176,0,(int)Math.ceil(furnace.progress*33),10);if(furnace.maxBurnTime>0){int b=furnace.burnTime*14/furnace.maxBurnTime;drawLegacyRegion(g,26,69-b,176,24-b,14,b);}if(furnace.output!=null){int color=furnace.output.material.moltenColor(),height=furnace.output.amount*52/RotaryFurnaceEntity.maxOutput();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);drawLegacyRegion(g,98,70-height,176,76-height,16,height);g.setColor(1,1,1,1);g.flush();var out=g.bufferSource().getBuffer(RotaryFurnaceGuiTypes.GLOW);float px=leftPos+98,py=topPos+70-height,u=176/256F,v=(76-height)/256F;var pose=g.pose().last();out.addVertex(pose,px,py,0).setUv(u,v).setColor(1F,1F,1F,.3F);out.addVertex(pose,px,py+height,0).setUv(u,76/256F).setColor(1F,1F,1F,.3F);out.addVertex(pose,px+16,py+height,0).setUv(192/256F,76/256F).setColor(1F,1F,1F,.3F);out.addVertex(pose,px+16,py,0).setUv(192/256F,v).setColor(1F,1F,1F,.3F);g.flush();}horizontal(g,furnace.tanks[0]);vertical(g,furnace.tanks[1],134);vertical(g,furnace.tanks[2],152);}
 private void vertical(GuiGraphics g,FluidTank tank,int x){int height=tank.getFill()*52/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);for(int drawn=0;drawn<height;){int piece=Math.min(16,height-drawn);g.blit(tank.getTankType().getTexture(),leftPos+x,topPos+70-drawn-piece,0,16-piece,16,piece,16,16);drawn+=piece;}g.setColor(1,1,1,1);}
 private void horizontal(GuiGraphics g,FluidTank tank){int width=tank.getFill()*52/tank.getMaxFill();if(width<=0)return;g.flush();int color=tank.getTankType().getTint();RenderSystem.setShader(GameRenderer::getPositionTexColorShader);RenderSystem.setShaderTexture(0,tank.getTankType().getTexture());RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();var out=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_TEX_COLOR);var matrix=g.pose().last().pose();int x=leftPos+8,y=topPos+36;float u=1-width/16F;out.addVertex(matrix,x,y+16,0).setUv(1,1).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x+width,y+16,0).setUv(u,1).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x+width,y,0).setUv(u,0).setColor(color>>16&255,color>>8&255,color&255,255);out.addVertex(matrix,x,y,0).setUv(1,0).setColor(color>>16&255,color>>8&255,color&255,255);BufferUploader.drawWithShader(out.buildOrThrow());RenderSystem.disableBlend();}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var furnace=machine();if(furnace==null)return;if(legacyInfoHovered(x,y,8,36,52,16))tankInfo(g,furnace.tanks[0],x,y);if(legacyInfoHovered(x,y,134,18,16,52))tankInfo(g,furnace.tanks[1],x,y);if(legacyInfoHovered(x,y,152,18,16,52))tankInfo(g,furnace.tanks[2],x,y);if(legacyInfoHovered(x,y,44,54,16,16)&&!menu.getSlot(4).hasItem()){var lines=fuelHelp();if(!lines.isEmpty())g.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,98,18,16,52)){boolean leftShift=com.mojang.blaze3d.platform.InputConstants.isKeyDown(minecraft.getWindow().getWindow(),org.lwjgl.glfw.GLFW.GLFW_KEY_LEFT_SHIFT);g.renderTooltip(font,furnace.output==null?Component.translatable("gui.hbm.foundry.empty").withStyle(ChatFormatting.RED):furnace.output.material.displayName().copy().append(": ").append(HbmMaterials.formatAmount(furnace.output.amount,leftShift)).withStyle(ChatFormatting.YELLOW),x,y);}}
 private void tankInfo(GuiGraphics g,FluidTank tank,int x,int y){var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+"/"+tank.getMaxFill()+"mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}
 private static List<Component> fuelHelp(){var lines=new ArrayList<Component>();var module=RotaryFurnaceConfig.BURN;String[] names={"log","wood","coal","lignite","coke","solid","rocket","balefire"};for(int pass=0;pass<2;pass++){var values=pass==0?module.getModTime():module.getModHeat();var section=new ArrayList<Component>();for(int i=0;i<values.length;i++)if(values[i]!=1D){double bonus=values[i]-1;String value=(bonus<0?"":"+")+(int)(bonus*100)+"%";section.add(Component.literal("- ").append(Component.translatable("gui.hbm.rotary_furnace.fuel_"+names[i])).append(": ").append(Component.literal(value).withStyle(bonus<0?ChatFormatting.RED:ChatFormatting.GREEN)).withStyle(ChatFormatting.YELLOW));}if(!section.isEmpty()){lines.add(Component.translatable(pass==0?"gui.hbm.rotary_furnace.time_bonus":"gui.hbm.rotary_furnace.heat_bonus").withStyle(pass==0?ChatFormatting.GOLD:ChatFormatting.RED));lines.addAll(section);}}return lines;}
}
